<script setup>import {reactive,ref,onMounted} from 'vue';import {getConfig,createTest} from '../api';import ModelSelector from '../components/ModelSelector.vue';import AudioSourcePanel from '../components/AudioSourcePanel.vue';import ResultPanel from '../components/ResultPanel.vue';
const cfg=ref({languages:[],models:[],samples:[]}),selected=ref([]),loading=ref(false),results=ref([]),error=ref('');const form=reactive({sampleId:'',file:null,recording:false,url:'',start:0,end:0,language:'中文',title:'',scene:'日常对话',blind:false});onMounted(async()=>{cfg.value=await getConfig();selected.value=cfg.value.models.slice(0,2).map(x=>x.id)});async function submit(){error.value='';if(!selected.value.length)return error.value='请至少选择一个 ASR 模型';loading.value=true;results.value=[];try{const models=cfg.value.models.filter(m=>selected.value.includes(m.id));const r=await createTest({...form,models});results.value=r.results||[]}catch(e){error.value=e.message}finally{loading.value=false}}</script><template><div class="content"><div class="page-title"><div><p class="eyebrow">ONLINE EVALUATION</p><h1>在线测评</h1><p>选择一段真实语音，同时比较多个模型的识别表现。</p></div><span class="status-pill">● Mock / API 自动切换</span></div><div class="layout"><div><AudioSourcePanel :samples="cfg.samples" :form="form"/><section class="card"><h2>测评设置</h2><div class="grid-two"><label>测试名称<input v-model="form.title" placeholder="例如：中文会议场景"/></label><label>使用场景<select v-model="form.scene"><option>日常对话</option><option>会议发言</option><option>客服通话</option><option>短视频</option></select></label></div><label>语言<select v-model="form.language"><option v-for="l in cfg.languages">{{l}}</option></select></label><h3>ASR 模型 <small>可选择 1～3 个</small></h3><ModelSelector :models="cfg.models" v-model:selected="selected"/><label class="check"><input type="checkbox" v-model="form.blind"/>盲测模式（隐藏模型名称）</label><p v-if="error" class="error">{{error}}</p><button class="primary wide" :disabled="loading" @click="submit">{{loading?'正在识别…':'开始测评'}}</button></section></div><ResultPanel :loading="loading" :results="results"/></div></div></template>
